mapper.select:
SELECT ,
       COALESCE(b.sys09_code, '')  AS code,
       COALESCE(b.sys09_name, '')  AS name
  FROM sys13_code_group a
       LEFT OUTER JOIN sys09_code b ON a.sys13_code_id = b.sys09_code_id
 WHERE sys13_kind_group_cd = #{kindGroupCd}
   AND sys13_code_kind_id = #{codeKindId}
   AND sys13_code_id != 0
   AND sys09_company_id = #{companyId}

mapper.update:
UPDATE sys13_code_group
   SET sys13_kind_group_cd = #{kindGroupCd},
       sys13_kind_group_nm = #{kindGroupNm},
       sys13_note          = #{note}
 WHERE sys13_code_group_id = #{codeGroupId}

UPDATE sys13_code_group
   SET sys13_kind_group_cd = #{kindGroupCd}
     , sys13_kind_group_nm = #{kindGroupNm}
 WHERE sys13_code_kind_id  = #{codeKindId}
   AND sys13_kind_group_cd = #{oriKindGroupCd}
   AND sys13_kind_group_nm = #{oriKindGroupNm}

mapper.delete:
DELETE FROM sys13_code_group
 WHERE sys13_code_kind_id  = #{codeKindId}
   AND sys13_kind_group_cd = #{kindGroupCd}
   AND sys13_kind_group_nm = #{kindGroupNm}
